export function buildStores(): StoreRecord[] {
  return STORES_WITH_COORDS.map((s) => ({
    id: Number(s.code),
    code: s.code,
    name: s.name,
    address: s.address,
    district: s.district,
    zip: formatCEP(s.zip),
    city: s.city,
    state: s.state,
    fullAddress: `${s.address}, ${s.district}, ${s.city}, ${s.state}, Brasil`,
    lat: s.lat,
    lng: s.lng,
  }));
}

export const ALL_STORES = buildStores();
